<?php
require __DIR__.'/wp-load.php';
$checks=0; function ccheck($ok,$label){global $checks;$checks++;if(!$ok)throw new RuntimeException('Catalog: '.$label);}
function cm($name,...$args){return(new ReflectionMethod('AISA_Agent',$name))->invoke(null,...$args);}
function cr($route,$uid,$data,$nonce=true){global $wp_rest_auth_cookie;wp_set_current_user($uid);$wp_rest_auth_cookie=$uid>0;unset($_REQUEST['_wpnonce'],$_SERVER['HTTP_X_WP_NONCE']);if($uid)$_SERVER['HTTP_X_WP_NONCE']=$nonce?wp_create_nonce('wp_rest'):'invalid-synthetic';$r=new WP_REST_Request('POST','/aisa/v1/'.$route);$r->set_header('Content-Type','application/json');$r->set_body(wp_json_encode($data));$server=rest_get_server();$auth=$server->check_authentication();return is_wp_error($auth)?rest_convert_error_to_response($auth):$server->dispatch($r);}
function cp($name,$status='publish',$visibility='visible',$password=''){$p=new WC_Product_Simple();$p->set_name($name);$p->set_status($status);$p->set_catalog_visibility($visibility);$p->set_regular_price('19.75');$p->set_short_description('Synthetic public description. कोई invented license नहीं।');$p->set_purchase_note('PRIVATE_PURCHASE_NOTE_CANARY');$id=$p->save();if($password!=='')wp_update_post(array('ID'=>$id,'post_password'=>$password));return$id;}
function ca($id){AISA_Agent::sync($id);$record=cm('source_id',$id);update_post_meta($record,'aisa_approved_hash',AISA_Agent::review_signature(get_post($record)));return$record;}
$saved=AISA_Agent::settings();$roles=get_option('wp_user_roles');$policy=get_option('woocommerce_downloads_require_login');
// Exercise manual-review mode here; fresh default auto-catalog has separate native coverage.
