$calls=0;$prompts=array();$mode='ok';$active=0;$record=0;$mail=0;
add_filter('pre_wp_mail',function($v)use(&$mail){$mail++;return false;});
add_filter('pre_http_request',function($pre,$args,$url)use(&$calls,&$prompts,&$mode,&$active,&$record){if($url!=='https://catalog.fixture.invalid/chat')throw new RuntimeException('Unexpected external destination');$calls++;$prompts[]=$args['body'];if($mode==='hide'){$p=wc_get_product($active);$p->set_catalog_visibility('hidden');$p->save();}if($mode==='price'){$p=wc_get_product($active);$p->set_regular_price('29.25');$p->save();}if($mode==='revoke')delete_post_meta($record,'aisa_approved_hash');if($mode==='failure')return new WP_Error('fixture','RAW_PRIVATE_ERROR');return array('headers'=>array(),'response'=>array('code'=>200,'message'=>'Synthetic'),'body'=>wp_json_encode(array('choices'=>array(array('message'=>array('role'=>'assistant','content'=>'Synthetic approved product answer. नमस्ते।'),'finish_reason'=>'stop')))));},PHP_INT_MAX,3);
$public=array();for($i=0;$i<29;$i++){ $pid=cp('Public product '.$i);$product=wc_get_product($pid);$product->set_date_created(time()-DAY_IN_SECONDS*(1+(($i*7)%5)));$product->save();$public[]=$pid; }
$latest=$public;usort($latest,function($a,$b){$date=strcmp(get_post($b)->post_date,get_post($a)->post_date);return$date?:$b<=>$a;});ccheck($latest!==$public&&$latest!==array_reverse($public),'date fixture differs from ascending and descending ID order');
$draft=cp('DRAFT_CANARY','draft');$private=cp('PRIVATE_CANARY','private');$hidden=cp('HIDDEN_CANARY','publish','hidden');$password=cp('PASSWORD_CANARY','publish','visible','synthetic-do-not-authenticate');$search=cp('SEARCH_ONLY_CANARY','publish','search');$trash=cp('TRASH_CANARY','trash');
wp_set_current_user(0);$scope=AISA_Memory::scope();
$queryArgs=array();$capture=function($args)use(&$queryArgs){$queryArgs[]=$args;return$args;};add_filter('woocommerce_product_object_query_args',$capture);
$seen=array();$page=1;do{$r=cr('browse_catalog',0,array('scope'=>$scope,'page'=>$page));ccheck($r->get_status()===200,'public page succeeds');$d=$r->get_data();ccheck(count($d['products'])<=12&&$d['batch_size']===12,'fixed page bound');ccheck(str_contains($r->get_headers()['Cache-Control'],'no-store'),'uncached public/session response');foreach($d['products']as$p){$seen[]=$p['id'];ccheck(array_keys($p)===array('id','ai_ready','name','price','description','url','available','display_price','image','commerce'),'whitelisted product fields only');ccheck(!$p['ai_ready']&&!str_contains(wp_json_encode($p),'PRIVATE_'),'pending public facts browse without private metadata');} $page=$d['next_page'];}while($page!==null&&$page<10);
