$filtered=array();for($n=1;$n<=3;$n++){$r=cr('browse_catalog',0,array('scope'=>$scope,'page'=>$n,'query'=>'Public product','maximum'=>20));ccheck($r->get_status()===200,'legacy filtered page still succeeds');foreach($r->get_data()['products']as$item)$filtered[]=$item['id'];}ccheck($filtered===$latest,'retained filtered API follows same newest-date stable ties');
foreach(array(0,-1,1.5,'1',array(1),1000001)as$bad){ccheck(cr('browse_catalog',0,array('scope'=>$scope,'page'=>$bad))->get_status()===400,'invalid page rejected');}
ccheck(cr('browse_catalog',0,array('scope'=>'other-site','page'=>1))->get_status()===409,'scope mismatch rejected');
