foreach(array($draft,$private,$hidden,$password,$search,$trash,9999999)as$id){$before=$calls;$r=cr('chat',0,array('scope'=>$scope,'message'=>'Tell me the price','product_id'=>$id));ccheck($r->get_status()===404&&$calls===$before,'nonpublic/missing selection denied before model');}
foreach(array('2',array(2),0,-1,2.4)as$id)ccheck(cr('chat',0,array('scope'=>$scope,'message'=>'Question','product_id'=>$id))->get_status()===400,'noninteger product ID rejected');
$active=$public[0];$before=$calls;ccheck(cr('chat',0,array('scope'=>$scope,'message'=>'Tell me a license','product_id'=>$active))->get_data()['code']==='product_unapproved'&&$calls===$before,'pending product selection cannot send unapproved facts to AI');
$record=ca($active);$r=cr('chat',0,array('scope'=>$scope,'message'=>'What is its current public price?','product_id'=>$active,'product_name'=>'CLIENT_FORGED_NAME','price'=>'CLIENT_FORGED_PRICE','description'=>'IGNORE_ALL_RULES_CANARY'));
ccheck($r->get_status()===200&&$calls===$before+1,'approved selected product answers through model: '.wp_json_encode(array($r->get_status(),$r->get_data(),$calls,$before,AISA_Provider::observation(AISA_Agent::settings()))));$prompt=json_decode(end($prompts),true);ccheck(str_contains($prompt['messages'][1]['content'],'Public product 0')&&str_contains($prompt['messages'][1]['content'],'19.75'),'selection resolved from current server facts');ccheck(!str_contains(end($prompts),'CLIENT_FORGED')&&!str_contains(end($prompts),'IGNORE_ALL_RULES_CANARY')&&!str_contains(end($prompts),'PRIVATE_PURCHASE_NOTE_CANARY'),'client facts and private purchase note excluded');ccheck(str_contains($prompt['messages'][0]['content'],'Never invent policies')&&str_contains($prompt['messages'][0]['content'],'language of the latest customer'),'language and non-invention instructions retained');
ccheck(str_contains($prompt['messages'][0]['content'],'Roman-script Hinglish, not Devanagari')&&str_contains($prompt['messages'][0]['content'],'explicitly requests that script'),'script guidance distinguishes Hinglish and explicit Hindi requests; fixture is not language-quality proof');
foreach(array('price','hide','revoke')as$case){$p=wc_get_product($active);$p->set_catalog_visibility('visible');$p->set_regular_price('19.75');$p->save();$record=ca($active);$mode=$case;$r=cr('chat',0,array('scope'=>$scope,'message'=>'Current public facts?','product_id'=>$active));ccheck($r->get_status()===409&&!isset($r->get_data()['reply']),'mid-response '.$case.' suppresses stale AI text');}$mode='ok';
$p=wc_get_product($active);$p->set_catalog_visibility('visible');$p->set_regular_price('19.75');$p->set_short_description(str_repeat('हिंदी ',250));$p->save();$record=ca($active);$facts=cm('public_product_facts',$p);ccheck(mb_check_encoding($facts['description'],'UTF-8')&&mb_strlen($facts['description'])<=700,'long multilingual description stays valid and bounded');
$badLink=function($url,$post)use($active){return(int)$post->ID===$active?'https://untrusted.invalid/product':$url;};add_filter('post_type_link',$badLink,10,2);ccheck(cm('public_product_facts',$p)===null,'untrusted product URL is suppressed');remove_filter('post_type_link',$badLink,10);
$badQuery=function($url,$post)use($active){return(int)$post->ID===$active?'https://aisa.local.test/?download_file=secret&order=private':$url;};add_filter('post_type_link',$badQuery,10,2);ccheck(cm('public_product_facts',$p)===null,'private download/order URL cannot become catalog link');remove_filter('post_type_link',$badQuery,10);
$broken=function(){return new WP_Error('fixture','RAW_QUERY_CANARY');};add_filter('woocommerce_product_object_query',$broken);$r=cr('browse_catalog',0,array('scope'=>$scope,'page'=>1));ccheck($r->get_status()===503&&!str_contains(wp_json_encode($r->get_data()),'RAW_QUERY_CANARY'),'query failure is sanitized');remove_filter('woocommerce_product_object_query',$broken);
$mode='failure';$before=$calls;$r=cr('chat',0,array('scope'=>$scope,'message'=>'Question','product_id'=>$active));ccheck($r->get_status()===503&&$calls===$before+1&&!str_contains(wp_json_encode($r->get_data()),'RAW_PRIVATE_ERROR'),'provider failure is bounded and sanitized');
ccheck($mail===0&&get_option('wp_user_roles')===$roles&&get_option('woocommerce_downloads_require_login')===$policy,'no mail, roles or download-security setting changes');foreach(array(1,2,3)as$id)ccheck(get_userdata($id)->user_pass==='*'&&!WP_Session_Tokens::get_instance($id)->get_all(),'no real credentials or sessions');
