update_option('aisa_settings',$saved);echo wp_json_encode(array('status'=>'PASS','version'=>AISA_VERSION,'checks'=>$checks,'commerce_checks'=>$commerceChecks,'provider_calls'=>'intercepted synthetic only','real_login_verified'=>false,'external_sends'=>0,'catalog_scope'=>'all public shop/catalog-visible products; search-only visibility is respected'));
